const zones=[{range:'0—200 METRES',title:'The sunlit<br><em>shallows.</em>',description:'Here, sunlight reaches through the water and life gathers in color. This is the ocean most of us think we know.',feature:'Drifting moon jelly',symbol:'✳',className:''},{range:'200—1,000 METRES',title:'The twilight<br><em>zone.</em>',description:'Sunlight fades to a trace. In the dim blue, movement, shimmer and silhouette take on a different meaning.',feature:'The glowing lanternfish',symbol:'✦',className:'twilight'},{range:'1,000—4,000 METRES',title:'The midnight<br><em>world.</em>',description:'Beyond the reach of sunlight, life persists in remarkable forms. Here, darkness is simply another habitat.',feature:'Slow-growing deep-sea coral',symbol:'✺',className:'midnight'}];const tabs=[...document.querySelectorAll('.depth-tab')];function selectDepth(i,focus=false){const z=zones[i];tabs.forEach((tab,n)=>{tab.classList.toggle('active',n===i);tab.setAttribute('aria-selected',n===i?'true':'false');tab.tabIndex=n===i?0:-1});if(focus)tabs[i].focus();document.querySelector('#depthVisual').className='depth-visual '+z.className;document.querySelector('#depthIndex').textContent=String(i+1).padStart(2,'0');document.querySelector('#depthRange').textContent=z.range;document.querySelector('#depthTitle').innerHTML=z.title;document.querySelector('#depthDescription').textContent=z.description;document.querySelector('#depthFeature').textContent=z.feature;document.querySelector('#depthSymbol').textContent=z.symbol}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectDepth(i));tab.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowDown'){e.preventDefault();selectDepth((i+1)%tabs.length,true)}if(e.key==='ArrowLeft'||e.key==='ArrowUp'){e.preventDefault();selectDepth((i+tabs.length-1)%tabs.length,true)}})});selectDepth(0);document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button?'true':'false')});document.querySelectorAll('.specimen-card').forEach(card=>card.hidden=button.dataset.filter!=='all'&&!card.dataset.category.split(' ').includes(button.dataset.filter))}));
